package com.huy.enterprise.risk; import com.huy.enterprise.common.enums.*; import jakarta.validation.constraints.*; import java.time.OffsetDateTime; import java.util.UUID; record RiskRequest(@NotBlank String title,@NotNull RiskType riskType,@NotNull ImpactLevel impactLevel,String description,OffsetDateTime detectedAt,RiskEventStatus status,UUID supplierId,UUID productId,UUID purchaseOrderId,UUID shipmentId){} record RiskStatusRequest(@NotNull RiskEventStatus status){} record RiskResponse(UUID id,String title,RiskType riskType,ImpactLevel impactLevel,String description,OffsetDateTime detectedAt,RiskEventStatus status,UUID supplierId,UUID productId,UUID purchaseOrderId,UUID shipmentId){static RiskResponse from(RiskEvent r){return new RiskResponse(r.getId(),r.getTitle(),r.getRiskType(),r.getImpactLevel(),r.getDescription(),r.getDetectedAt(),r.getStatus(),r.getSupplier()==null?null:r.getSupplier().getId(),r.getProduct()==null?null:r.getProduct().getId(),r.getPurchaseOrder()==null?null:r.getPurchaseOrder().getId(),r.getShipment()==null?null:r.getShipment().getId());}}
